"use client";

import * as React from "react";
import styles from "../styles/skeleton-shimmer.module.css";

export interface SkeletonShimmerProps {
  /** Number of body lines */
  lines?: number;
  /** Show the avatar + title block */
  avatar?: boolean;
  /** Avatar shape */
  avatarShape?: "rounded" | "circle";
  /** Wrap the placeholder in a bordered card */
  card?: boolean;
  /** Seconds per shimmer sweep */
  speed?: number;
  /** Placeholder block color (defaults to the theme's raised surface) */
  baseColor?: string;
  /** Shimmer highlight color */
  shimmerColor?: string;
  /** Corner radius of the bars in pixels */
  radius?: number;
  /** Width in pixels */
  width?: number;
  /** Accessible loading label */
  label?: string;
  /** Optional className merged onto the root */
  className?: string;
  /** Optional inline styles merged onto the root */
  style?: React.CSSProperties;
}

// Deterministic widths so server and client markup match.
const LINE_WIDTHS = ["100%", "100%", "62%", "88%", "74%", "94%", "56%"];

export function SkeletonShimmer({
  lines = 3,
  avatar = true,
  avatarShape = "rounded",
  card = true,
  speed = 1.6,
  baseColor,
  shimmerColor = "rgba(255, 255, 255, 0.09)",
  radius = 6,
  width = 360,
  label = "Loading content",
  className = "",
  style,
}: SkeletonShimmerProps) {
  const count = Math.max(0, Math.min(7, Math.round(lines)));
  const widths = Array.from({ length: count }, (_, i) => (i === count - 1 && count > 1 ? "58%" : LINE_WIDTHS[i]));

  return (
    <div
      role="status"
      aria-busy="true"
      aria-label={label}
      className={`${styles.root} ${card ? styles.card : ""} ${className}`.trim()}
      style={
        {
          "--mf-sk-speed": `${Math.max(0.4, speed)}s`,
          "--mf-sk-shine": shimmerColor,
          "--mf-sk-radius": `${radius}px`,
          "--mf-sk-width": `${width}px`,
          ...(baseColor ? { "--mf-sk-base": baseColor } : null),
          ...style,
        } as React.CSSProperties
      }
    >
      {avatar && (
        <div className={styles.head} aria-hidden="true">
          <span className={`${styles.bar} ${styles.avatar} ${avatarShape === "circle" ? styles.circle : ""}`.trim()} />
          <span className={styles.titles}>
            <span className={styles.bar} style={{ width: "72%" }} />
            <span className={styles.bar} style={{ width: "44%" }} />
          </span>
        </div>
      )}
      {count > 0 && (
        <div className={styles.body} aria-hidden="true">
          {widths.map((w, i) => (
            <span key={i} className={styles.bar} style={{ width: w }} />
          ))}
        </div>
      )}
    </div>
  );
}

.root {
  display: flex;
  flex-direction: column;
  gap: 1.125rem;
  width: var(--mf-sk-width, 360px);
  max-width: 100%;
  color: var(--mf-fg, #f4f4f6);
}

.card {
  padding: 1.5rem;
  border: 1px solid var(--mf-border, #2e2e38);
  border-radius: 1.125rem;
  background-color: var(--mf-surface, #141419);
}

.head {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.titles {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 0.625rem;
}

.body {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

/* Every bar runs the same sweep on the same clock, so the shimmer reads as one band across the card. */
.bar {
  display: block;
  height: 0.75rem;
  border-radius: var(--mf-sk-radius, 6px);
  background-color: var(--mf-sk-base, var(--mf-surface-raised, #1b1b22));
  background-image: linear-gradient(100deg, transparent 20%, var(--mf-sk-shine, rgba(255, 255, 255, 0.09)) 40%, transparent 60%);
  background-size: 200% 100%;
  background-repeat: no-repeat;
  animation: mf-sk-sweep var(--mf-sk-speed, 1.6s) ease-in-out infinite;
}

.avatar {
  flex-shrink: 0;
  width: 3rem;
  height: 3rem;
  border-radius: calc(var(--mf-sk-radius, 6px) * 2);
}

.circle {
  border-radius: 999px;
}

@keyframes mf-sk-sweep {
  from {
    background-position: 150% 0;
  }
  to {
    background-position: -50% 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .bar {
    animation: none;
    background-image: none;
  }
}

