export function SkeletonShimmerTailwind() {
  const bar = "block h-3 rounded-md bg-zinc-800 bg-[linear-gradient(100deg,transparent_20%,rgba(255,255,255,0.09)_40%,transparent_60%)] bg-[length:200%_100%] animate-[shimmer_1.6s_ease-in-out_infinite]";
  return (
    <div role="status" aria-busy="true" aria-label="Loading content" className="flex w-80 flex-col gap-4 rounded-2xl border border-zinc-800 bg-zinc-950 p-6">
      <div className="flex items-center gap-4">
        <span className={`${bar} h-12 w-12 rounded-xl`} />
        <span className="flex flex-1 flex-col gap-2.5">
          <span className={`${bar} w-3/4`} />
          <span className={`${bar} w-1/2`} />
        </span>
      </div>
      <span className={bar} />
      <span className={bar} />
      <span className={`${bar} w-3/5`} />
      <style>{"@keyframes shimmer{from{background-position:150% 0}to{background-position:-50% 0}}"}</style>
    </div>
  );
}
